var jmShad;

function setup() {
  createCanvas(1112,834,WEBGL);
  noStroke();
  fill(240,177,51);
  jmShad = createShader(vert, frag);

}

function draw() {  
  this.shader(jmShad);
  background(0);
  rectMode(CENTER);
  jmShad.setUniform('resolution',[width*0.5,height*0.5]);
  jmShad.setUniform('time',millis()/400);
  rect(0,0,width,height);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}


// === Tab: tab2 ===
var frag=`

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 resolution;
uniform float time;

const float nb=200.0;

 vec4 quaternion(vec3 axis, float theta){
   axis=normalize(axis);
  return vec4(axis*sin(theta/2.0),cos(theta/2.0));}

vec3 qtourne(vec4 q, vec3 v){return v+2.0*cross(cross(v,q.xyz)-q.w*v,q.xyz);}

vec3 coupe(vec2 st){
  float time0=time*0.8;
 vec4 quat=quaternion(normalize(vec3(1.1+sin(2.0*time0),1.3+cos(time0),2.0+cos(0.2*time0))),time0*0.1);
  vec3  st3=vec3(st.y*st.y,st.x*st.x,st.x*st.y);
  st3=qtourne(quat,st3);
  vec3 col=vec3(st3.y,abs(-0.1+st3.z),st3.x);

  st=st3.xy*nb;
  float somme=floor(st.x/(-1.0+st.y*st.y))+floor(st.y/(2.0+st.x*st.x));
  if(mod(somme,2.0) > 0.1){col=vec3(1.0,min(somme*2.0,1.0),0.2);}
  return col;
}

void main(){
  vec2 st = gl_FragCoord.xy/resolution.xy;
st.x=st.x*0.5-1.0;
st.y=st.y*0.5-1.1;
  vec3 couleur = coupe(st);
  gl_FragColor = vec4( coupe(vec2(abs(couleur.x*couleur.y*354.4),abs(couleur.y*couleur.z*354.4))), 1.0 );
}  
`;

// === Tab: tab3 ===
var vert=`
     #ifdef GL_ES
      precision mediump float;
      #endif

    // 
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    //
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }    
`;

